@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

abstract class Role {
  + RoleID : int
}

class BusinessOwner {}
class HungryCustomer {}
class Entertainer {}

User "1" -- "0..*" Role

BusinessOwner --|> Role
BusinessOwner "0..*" -- "*" PizzaRestaurant

PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : time[]
}

PizzaRestaurant "1" -- "*" Pizza

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

HungryCustomer --|> Role
HungryCustomer "0..*" -- "*" Order

Order {
  + OrderID : int
  + OrderDate : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

EntertainmentOrder {
  + EntertainmentType : string
  + Duration : time
}

Order "1" -- "0..1" EntertainmentOrder

Entertainer --|> Role
Entertainer "0..*" -- "*" Availability

Availability {
  + Day : day
  + PizzaRestaurantID : int
}

PizzaRestaurant "1" -- "*" Entertainer

@enduml

